# frozen_string_literal: true

# 1.18.0-rf #1289 — SVG icons in place of emoji.
#
# Emoji render differently on every OS, cannot take the theme's colour, and a
# screen reader announces them by their emoji name ("open file folder"). These
# icons are Lucide's (lib/data/lucide), drawn from one sprite the layouts render
# once per page (shared/_icon_sprite, generated by bin/build_icon_sprite), so an
# icon is a few bytes of <use href="#i-NAME"> with no CDN, font or CSP change.
#
#   icon("house")                      decorative: hidden from screen readers
#   icon("circle-question-mark", label: "Help")   meaningful: role=img + name
#
# Strokes use currentColor, so an icon follows the text (and layer) colour in
# both themes. An unknown name raises: a missing icon is a programming error,
# and the helper spec renders every name the views use.
module IconHelper
  # The names the sprite holds, read once from the vendored provenance.
  def self.names
    @names ||= JSON.parse(Rails.root.join("lib/data/lucide/provenance.json").read)
                   .fetch("icons").map { |i| i.fetch("name") }.freeze
  end

  def icon(name, label: nil, css_class: nil)
    name = name.to_s
    raise ArgumentError, "unknown icon #{name.inspect} (see lib/data/lucide/provenance.json)" unless IconHelper.names.include?(name)

    attrs = { class: [ "sparc-icon", css_class ].compact.join(" "), focusable: "false" }
    attrs.merge!(label.present? ? { role: "img", "aria-label": label } : { "aria-hidden": "true" })

    content_tag(:svg, tag.use(href: "#i-#{name}"), **attrs)
  end
end
